RUN_DIR=/tmp/compound-engineering-501/ce-code-review/20260927-212249-1a9231ef; python3 - "$RUN_DIR" <<'EOF'
import json,sys,pathlib
rd=pathlib.Path(sys.argv[1])
m=json.load(open(rd/"mechanical-findings-2.json"))
# source-detail map
detail={}
for name in ["correctness","security","adversarial","testing","maintainability","reliability"]:
    for f in json.load(open(rd/f"{name}.json")).get("findings",[]):
        detail[(name,f["line"])]=f
sel=[]
for f in m["findings"]:
    if f["#"] in (1,3,5,6,7):
        ev=[];why=None
        for r in f["reviewers"]:
            s=detail.get((r,f["line"]))
            if s:
                ev+=s.get("evidence",[]); why=why or s.get("why_it_matters")
        sel.append({"#":f["#"],"title":f["title"],"severity":f["severity"],"file":f["file"],"line":f["line"],"why_it_matters":why,"evidence":ev,"suggested_fix":f.get("suggested_fix")})
json.dump(sel,open(rd/"validator-input.json","w"),ensure_ascii=False,indent=1)
print(len(sel))
EOF

